{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "urgency",
  "per_column": [
    {
      "name": "signal_critical_vitals",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Presence of critical vital signs in the note is a clinical variable distinct from the urgency label and plausibly predictive of it; not a restatement or deterministic function of the recorded urgency."
    },
    {
      "name": "signal_acute_symptoms",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Acute symptom mentions are note-derived features external to the urgency variable that carry genuine predictive signal about urgency."
    },
    {
      "name": "signal_acute_onset",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Acute onset extracted from the note is an independent clinical descriptor plausibly correlated with urgency, not a restatement of it."
    },
    {
      "name": "signal_high_risk_dx",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "High-risk diagnosis flag is an outside variable with legitimate predictive relevance to urgency; it describes clinical content rather than the urgency label itself."
    },
    {
      "name": "signal_severe_pain",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Severe pain is a note signal external to urgency; though observed constant (all 0) here, semantically it is a valid predictor, only weak due to zero variance in this sample."
    },
    {
      "name": "urgency_signal_count",
      "role": "restatement",
      "is_predictor": false,
      "rationale": "This is a deterministic aggregation (sum) of the individual signal_* columns. As a composite of the same features it adds no independent information beyond them and is a mechanical roll-up rather than a new outside predictor."
    },
    {
      "name": "urgency_signal_tier",
      "role": "restatement",
      "is_predictor": false,
      "rationale": "A binned/thresholded version of urgency_signal_count, hence a deterministic function of the other columns; it re-expresses the same signal aggregation and contributes no new predictive leverage. Its 'urgency' naming also risks conflation with the focus label."
    }
  ],
  "n_predictors": 5,
  "predictive_utility": 0.55,
  "rationale": "Five of the added columns are genuine note-derived clinical signals (critical vitals, acute symptoms, acute onset, high-risk diagnosis, severe pain) that lie outside the urgency label and plausibly predict it, giving real predictive leverage beyond the original columns. The remaining two (count and tier) are deterministic aggregations/binnings of those signals and add no independent information. Predictive utility is moderate rather than high because several signals are extremely sparse (near-constant, one all-zero), limiting realized discriminative power in this sample."
}

